from __future__ import annotations

import ast
import csv
import json
import re
from calendar import monthrange
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET_DIR = Path("/app/dataset")


def _clamped_date(value: str) -> date | None:
    try:
        year_s, month_s, day_s = value.split("-")
        year, month, day = int(year_s), int(month_s), int(day_s)
        if not 1 <= month <= 12 or day < 1:
            return None
        return date(year, month, min(day, monthrange(year, month)[1]))
    except Exception:
        return None


def _first_weekday_in_month(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_period(work_date: date, anchor_weekday: int) -> tuple[int, int]:
    month_start = _first_weekday_in_month(
        work_date.year, work_date.month, anchor_weekday
    )
    if work_date < month_start:
        if work_date.month == 1:
            return work_date.year - 1, 12
        return work_date.year, work_date.month - 1
    return work_date.year, work_date.month


def _task_quality(performed_tasks: str, task_pay: dict[int, int]) -> int:
    try:
        task_ids = ast.literal_eval(performed_tasks)
    except Exception:
        return 0
    if not isinstance(task_ids, list) or not all(isinstance(x, int) for x in task_ids):
        return 0
    return 2 if all(task_id in task_pay for task_id in task_ids) else 1


def _recoverable_bonus(performed_tasks: str, task_pay: dict[int, int]) -> int:
    task_ids = (int(match) for match in re.findall(r"\d+", performed_tasks))
    return sum(task_pay.get(task_id, 0) for task_id in task_ids)


def _round_salary(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict[str, list[int]]:
    with (DATASET_DIR / "employees.csv").open(newline="", encoding="utf-8") as f:
        employees = {
            row["PESEL"]: Decimal(row["hourly_rate"])
            for row in csv.DictReader(f)
            if row.get("PESEL")
        }

    with (DATASET_DIR / "tasks.csv").open(newline="", encoding="utf-8") as f:
        task_pay = {
            int(row["task_id"]): int(row["pay_per_completion"])
            for row in csv.DictReader(f)
        }

    with (DATASET_DIR / "timesheet.csv").open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames or []
        raw_rows = list(reader)

    dated_rows: list[tuple[dict[str, str], date]] = []
    for row in raw_rows:
        work_date = _clamped_date(row["date"])
        if work_date is not None:
            dated_rows.append((row, work_date))

    if not dated_rows:
        return {pesel: [] for pesel in sorted(employees)}

    anchor_weekday = min(work_date for _, work_date in dated_rows).weekday()

    seen: set[tuple[str, ...]] = set()
    grouped: dict[tuple[str, tuple[int, int]], list[dict]] = defaultdict(list)
    periods: set[tuple[int, int]] = set()

    for row, work_date in dated_rows:
        pesel = row["employee_id"]
        if pesel not in employees:
            continue

        dedupe_key = tuple(row[name] for name in fieldnames if name != "id")
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)

        try:
            salary_amount = Decimal(row["salary_amount"])
            hours_worked = int(row["hours_worked"])
        except Exception:
            continue

        period = _billing_period(work_date, anchor_weekday)
        periods.add(period)
        grouped[(pesel, period)].append(
            {
                "id": int(row["id"]),
                "work_date": work_date,
                "hours_worked": hours_worked,
                "salary_amount": salary_amount,
                "bonus": _recoverable_bonus(row["performed_tasks"], task_pay),
                "task_quality": _task_quality(row["performed_tasks"], task_pay),
            }
        )

    ordered_periods = sorted(periods)
    result: dict[str, list[int]] = {}

    for pesel in sorted(employees):
        salaries: list[int] = []
        for period in ordered_periods:
            rows = grouped.get((pesel, period), [])
            if not rows:
                salaries.append(0)
                continue

            base_pay = max(row["salary_amount"] for row in rows)

            rows_by_running_salary: dict[Decimal, list[dict]] = defaultdict(list)
            for row in rows:
                if row["salary_amount"] > 0:
                    rows_by_running_salary[row["salary_amount"]].append(row)

            bonus = 0
            for salary_amount in sorted(rows_by_running_salary):
                candidates = rows_by_running_salary[salary_amount]
                chosen = sorted(
                    candidates,
                    key=lambda row: (
                        -row["hours_worked"],
                        -row["task_quality"],
                        -row["bonus"],
                        row["work_date"].toordinal(),
                        row["id"],
                    ),
                )[0]
                bonus += chosen["bonus"]

            salaries.append(_round_salary(base_pay + Decimal(bonus)))

        result[pesel] = salaries

    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
